INSERT INTO feature VALUES('sugared-spelling','printing','Sugared and explicit spellings','presentation-printer','implemented','ordinary',NULL,'Every printing face chooses the most-sugared form or the explicit one, sugared by default; the formatter is at token parity with the printer over whole declarations, bodies included, the declarations held out named by issue. A reduct the checker applies is written as its call in the explicit form, and a written call of one the checker would apply is left to it in the sugared form; so is a forgetting map the checker applies, written `forget[sort C = A](m) at Model(T)` with the carriers it solved, and a written call of a map is written as the map in the explicit form too. Either form writes a definition''s result `-F B` as `B`, the returner the lowering inserts, but a value at a world or a region, and a result `-F [E] B` as `[E] B`, the row before the type. Either form writes a derived path operation, `Path.step(p, q)`, `Path.back(p)` or `Path.ap(f, p)`, as the operation, and folds a returned transport that one derives into it. The sugared form writes a tail''s `return f(x)` or `return x + y` as the call, which the checker elaborates alike. A thunk type written where a value is read, a transport''s family among them, takes the value-function alias over its domain list, `(y : A, P) => B`: the parser reads a group closing before `=>` as the alias''s domains.','surface-pretty surface-lsp surface-format surface-parser','crates/surface-pretty/src/former.rs crates/surface-pretty/tests/goldens.rs crates/surface-dispatcher/tests/parity.rs crates/surface-format/tests/rewrite.rs crates/surface-parser/tests/grammar.rs corpus/model/include/reduct.gandr corpus/model/identity/model-counter-manifest.gandr corpus/model/identity/transport-dependent.gandr corpus/model/control/effect-rows.gandr',NULL,NULL);
